"""Exactly two bounded first-wave strengths on candidate A's unchanged layout."""
import hashlib,json,shutil
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/v22r-burst';D.mkdir(exist_ok=True)
source=R/'variants/V22R-fast-A';base=json.loads((source/'params.json').read_text(encoding='utf8'));rows=[]
for label,cap,spread,finish,pose in [('C1',2,.09,.7,1.2),('C2',3,.045,1.4,1.6)]:
 c=dict(base,duration=3.5,openingBurst=True,openingPendingArrowCap=cap,openingDrawStagger=spread,openingFinishWoundedWeight=finish,impactPoseScale=pose)
 assert not c.get('safeFrontEngagement') and c['archerRange']==34 and c['arrowSpeed']==72
 v=R/('variants/V22R-'+label);v.mkdir(exist_ok=True);(v/'params.json').write_text(json.dumps(c,indent=2),encoding='utf8');(D/(label+'-requested-params.json')).write_text(json.dumps(c,indent=2),encoding='utf8')
 if (source/'asset-render-audit.json').exists():shutil.copyfile(source/'asset-render-audit.json',v/'asset-render-audit.json')
 rows.append(dict(label=label,variant='V22R-'+label,maxOpeningArrowsReservedPerTarget=cap,firstDrawStagger=spread,finishWoundedPreference=finish,upperBodyHitPoseScale=pose,maximumUpperBodyZOffset=.13*pose,worldReverseImpulse=0))
proposal=dict(baseline='2c821e1 / V22R-fast-A',candidates=rows,unchanged=['Scene, light, fixed camera, initial unit positions and blue assembly targets','Red motion controller, preferred speed, acceleration and original wounded slowdown','Each shooter original aim, draw, recovery and subsequent-shot rules','Arrow speed 72, range 34, original per-shooter damage 3 if j%17==0 else 1','Minimum enemy clearance and original autoCut buffer'],changes=['First shots use pending-damage-capacity-limited reservations instead of one in-flight arrow excluding every other first shooter. No overkill promises are scheduled.','Unshot members get a stable short range-valid draw stagger; no simultaneous full volley.','First target selection spreads across exposed platoons; C2 can prefer actually wounded members.','Real-hit upper-body pulse amplitude increased modestly, with unchanged duration and zero added root displacement. Death uses original fall, no launch.'],sourceHashes={name:hashlib.sha256((R/name).read_bytes()).hexdigest() for name in ['src/castle-approved-v22r.js','src/environment-native-v22.js','public/native-scenes/CastleExterior-scene/manifest.json','tools/motion_v22.py','tools/motion_v17.py']},limitations=['Original wall-crossing layout and initial rear-army cropping remain; no permission inferred to relocate scenery or armies.','More casualties do not guarantee additional safe time; static dead bodies still count in safety and collision.'],formalRender=False)
(D/'proposal.json').write_text(json.dumps(proposal,indent=2),encoding='utf8');print(json.dumps(proposal,indent=2))
